review.body:
I found a regression for document markup with few attributes. The inline comment points to the loss of cached opening-tag bytes.

I compared independent, complete stable-channel `NODE_PROD` builds of `d71b5372` and `925ee4a8` on Node 24.22.1, macOS arm64. A component builds 300 sections of headings, paragraphs, emphasis and lists on each render, producing 92,920 identical bytes:

| Public API | Base | Head |
| --- | ---: | ---: |
| `server.node.renderToPipeableStream` | 0.603 ms | 0.716 ms |
| `server.browser.renderToReadableStream` | 0.825 ms | 1.256 ms |
| `server.edge.renderToReadableStream` | 0.854 ms | 1.355 ms |

Each measurement drains the stream completely. I used 20 warmups, seven samples per workload/API, and fresh processes in base/head/head/base order. Each sample stops at 150 ms or 500 renders. The figures are medians of the two process medians. These are local renderer timings; HTTP throughput and other engines weren't measured.

The attribute-bearing row control improves substantially. A separate head/diagnostic/diagnostic/head comparison restores the document performance by retaining cached chunks only when no attributes were appended, while keeping that row improvement. Encoder counting ran separately from timing. All 208 HTML comparisons stayed identical, and the six focused production test suites passed on both original snapshots.

The script below is the exact harness used. Run it against each snapshot's independently built `build` directory:

```sh
NODE_ENV=production node fizz-batch-public.cjs /absolute/path/to/build focused result.json
```

Use `counts` instead of `focused` for the untimed encoder counts. The harness also contains the output-comparison fixtures used during review.

<details>
<summary>Renderer benchmark and controls</summary>

```js
'use strict';

// Local PR-review harness. Run against independently built complete snapshots.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const {Writable} = require('node:stream');
const {performance} = require('node:perf_hooks');
const {createHash} = require('node:crypto');

const [build, mode, output] = process.argv.slice(2);
const React = require(path.join(build, 'node_modules/react'));
const node = require(path.join(build, 'node_modules/react-dom/server.node'));
const browser = require(path.join(build, 'node_modules/react-dom/server.browser'));
const edge = require(path.join(build, 'node_modules/react-dom/server.edge'));
const h = React.createElement;
const digest = value => createHash('sha256').update(value).digest('hex');

async function render(api, element, {collect = true, slow = false, release, byob = false} = {}) {
  const chunks = [];
  let bytes = 0;
  let writes = 0;
  let maxChunk = 0;
  let prefix = '';
  const errors = [];
  function consume(chunk) {
    const buffer = collect || release ? Buffer.from(chunk) : chunk;
    bytes += buffer.length;
    writes++;
    maxChunk = Math.max(maxChunk, buffer.length);
    if (collect) chunks.push(buffer);
    if (release) {
      prefix += buffer.toString('utf8');
      if (prefix.includes('Loading fixture')) {
        const callback = release;
        release = null;
        queueMicrotask(callback);
      }
    }
  }
  if (api === 'legacy' || api === 'static') {
    consume(Buffer.from(api === 'legacy'
      ? node.renderToString(element)
      : node.renderToStaticMarkup(element)));
  } else if (api === 'node') {
    await new Promise((resolve, reject) => {
      const destination = new Writable({
        highWaterMark: slow ? 32 : 16384,
        write(chunk, encoding, callback) {
          consume(chunk);
          if (slow) setImmediate(callback);
          else callback();
        },
      });
      destination.on('finish', resolve);
      destination.on('error', reject);
      const stream = node.renderToPipeableStream(element, {
        onShellReady() { stream.pipe(destination); },
        onShellError: reject,
        onError(error) { errors.push(String(error)); },
      });
    });
  } else {
    const server = api === 'browser' ? browser : edge;
    const stream = await server.renderToReadableStream(element, {
      onError(error) { errors.push(String(error)); },
    });
    const reader = stream.getReader(byob ? {mode: 'byob'} : undefined);
    while (true) {
      const {done, value} = await (byob
        ? reader.read(new Uint8Array(257))
        : reader.read());
      if (value) consume(value);
      if (done) break;
      if (slow) await new Promise(resolve => setImmediate(resolve));
    }
  }
  assert.deepEqual(errors, []);
  return {html: collect ? Buffer.concat(chunks).toString('utf8') : undefined, bytes, writes, maxChunk};
}

function fixtures() {
  const cases = [
    ['primitive-attributes', h('div', {
      id: 'a"<&\'é😀', className: 'card active', tabIndex: 0, title: '',
      dir: 'ltr', role: 'region', hidden: false, inert: true,
      'aria-hidden': false, 'data-active': true, 'data-off': false,
      draggable: false, spellCheck: true, contentEditable: false,
      onClick() {}, 'data-empty': '', 'data-null': null,
    }, 'Text & < > "\' é😀')],
    ['style-values', h('div', {style: {
      display: 'grid', margin: 0, padding: 12, opacity: 0.5, lineHeight: 1.5,
      zIndex: 2, flex: 1, WebkitTransform: 'translateX(2px)', msTransition: 'none',
      backgroundImage: 'url("/image?a=1&b=2")', '--accent': '  red  ',
      '--spacing': 2, '--caption': '"é😀&"', border: null, outline: undefined,
    }}, 'Styled')],
    ['empty-style', h('div', {style: {display: null, color: undefined, margin: ''}})],
    ['anchors', h('div', null,
      h('a', {href: '', download: true}, 'Empty'),
      h('a', {href: '/file?a=1&b=2', download: 'a"b.txt'}, 'Named'),
      h('a', {href: '/file', download: false}, 'Not downloaded'))],
    ['object', h('object', {data: '/document?a=1&b=2', type: 'text/plain', width: 300}, 'Fallback')],
    ['select', h('select', {name: 'choice', defaultValue: 'b'},
      h('option', {value: 'a'}, 'A'), h('option', {value: 'b'}, 'B & C'))],
    ['multi-select', h('select', {name: 'choices', multiple: true, defaultValue: ['b', 'c']},
      h('option', {value: 'a'}, 'A'), h('option', {value: 'b'}, 'B'),
      h('optgroup', {label: 'Group'}, h('option', {value: 'c'}, 'C')))],
    ['textarea', h('textarea', {name: 'message', rows: 3, cols: 20, defaultValue: '\n<&é😀'})],
    ['input', h('div', null,
      h('input', {type: 'checkbox', name: 'enabled', defaultChecked: true, value: 'yes', readOnly: true}),
      h('input', {type: 'text', name: 'name', defaultValue: 'A"&é😀', required: true}),
      h('input', {type: 'file', capture: 'environment', multiple: true}))],
    ['url-form', h('form', {action: '/submit?a=1&b=2', method: 'post', encType: 'multipart/form-data'},
      h('input', {type: 'submit', name: 'input', value: 'Save', formAction: '/save', formMethod: 'post'}),
      h('button', {name: 'button', type: 'submit', formAction: '/preview', formTarget: '_blank'}, 'Preview'))],
    ['function-form', h('form', {action() {}},
      h('button', {formAction() {}}, 'Save'),
      h('input', {type: 'submit', formAction() {}, value: 'Submit'}))],
    ['svg', h('svg', {viewBox: '0 0 100 100', width: 100, height: '100', focusable: false},
      h('use', {xlinkHref: '/sprite.svg#icon'}),
      h('path', {d: 'M0 0L10 10', strokeWidth: 2, fillRule: 'evenodd', style: {strokeOpacity: 0.7}}),
      h('text', {xmlLang: 'en', xmlSpace: 'preserve'}, 'A & B'))],
    ['mathml', h('math', null, h('mi', {mathvariant: 'bold'}, 'x'))],
    ['custom-element', h('review-card', {
      className: 'card', active: true, inactive: false, label: '"é😀&',
      count: 3, style: {display: 'block', '--accent': 'purple'},
    }, 'Card')],
    ['preformatted', h('pre', {className: 'code', style: {whiteSpace: 'pre-wrap'}}, '\nA<&😀\nB')],
    ['inner-html', h('div', {id: 'wrapper', style: {display: 'block'}, dangerouslySetInnerHTML: {__html: '<b>Known content</b>'}})],
    ['self-closing', h('div', null, h('br'), h('hr', {className: 'rule'}),
      h('picture', null,
        h('source', {media: '(min-width: 600px)', srcSet: '/wide.png 1x, /wide2.png 2x'}),
        h('img', {loading: 'lazy', src: '/small.png', alt: 'Picture & caption', width: 300, height: 200})))],
    ['document-resources', h('html', {lang: 'en', 'data-empty': ''},
      h('head', {id: 'head'},
        h('title', {id: 'title'}, 'Review & test'),
        h('meta', {charSet: 'utf-8'}),
        h('meta', {name: 'viewport', content: 'width=device-width'}),
        h('link', {rel: 'stylesheet', href: '/style.css', precedence: 'base', media: 'screen'}),
        h('style', {nonce: 'local'}, 'body {color: red}'),
        h('script', {src: '/app.js', async: true, nonce: 'local'})),
      h('body', {style: {margin: 0}, 'data-empty': ''}, h('main', null, 'Content')))],
  ];
  for (const length of [0, 1, 200, 1300, 1365, 1366, 2047, 2048, 4095, 4096, 16384]) {
    cases.push([`large-ascii-${length}`, h('div', {
      'data-payload': 'a'.repeat(length), title: 'end', style: {'--label': 'z'.repeat(length)},
    }, 'Done')]);
    cases.push([`large-unicode-${length}`, h('div', {
      title: 'é😀漢'.repeat(Math.floor(length / 4)),
      style: {'--label': 'é😀漢'.repeat(Math.floor(length / 4))},
    }, 'Done')]);
  }
  return cases;
}

async function matrix() {
  const rows = [];
  for (const [name, element] of fixtures()) {
    for (const api of ['legacy', 'static', 'node', 'browser', 'edge']) {
      const value = await render(api, element);
      rows.push({name, api, ...value, sha256: digest(value.html)});
    }
  }
  const large = h('div', {'data-payload': 'a'.repeat(10000), style: {'--text': 'é😀漢'.repeat(2500)}}, 'Done');
  for (const api of ['node', 'browser', 'edge']) {
    for (const byob of api === 'node' ? [false] : [false, true]) {
      const value = await render(api, large, {slow: true, byob});
      rows.push({name: `slow-reader-byob-${byob}`, api, ...value, sha256: digest(value.html)});
    }
    let resolve;
    const Lazy = React.lazy(() => new Promise(done => {resolve = done;}));
    const element = h('main', {className: 'shell'},
      h(React.Suspense, {fallback: h('p', {style: {color: 'gray'}}, 'Loading fixture')}, h(Lazy)));
    const value = await render(api, element, {
      release() {
        resolve({default: () => h('section', {
          title: 'Resolved & complete', style: {padding: 10, '--accent': 'blue'},
        }, 'Resolved fixture')});
      },
    });
    assert.ok(value.html.includes('Resolved fixture'));
    rows.push({name: 'suspense-stream', api, ...value, sha256: digest(value.html)});
  }
  const style = rows.find(row => row.name === 'style-values' && row.api === 'node').html;
  assert.ok(style.includes('margin:0;padding:12px;opacity:0.5;line-height:1.5;z-index:2;flex:1'));
  assert.ok(style.includes('--accent:red;--spacing:2;--caption:&quot;é😀&amp;&quot;'));
  assert.equal(rows.find(row => row.name === 'empty-style' && row.api === 'node').html, '<div></div>');
  return rows;
}

function workloads() {
  const rows = 1000;
  const list = make => h('ul', null, Array.from({length: rows}, (_, index) => make(index)));
  const commonStyle = {
    display: 'flex', alignItems: 'center', gap: 8, margin: 0, padding: 12,
    color: '#222', backgroundColor: '#fff', borderRadius: 4, lineHeight: 1.5,
    fontSize: 14, fontWeight: 400, opacity: 0.9, flex: 1, minWidth: 0,
    maxWidth: '100%', position: 'relative', zIndex: 1, '--accent': 'blue',
  };
  return [
    ['text-control', h('pre', null, 'An ordinary line of document text.\n'.repeat(1000))],
    ['attribute-free', list(i => h('li', {key: i}, 'Item ' + i))],
    ['short-attributes', list(i => h('li', {key: i, className: 'row', title: 'Item ' + i}, 'Item ' + i))],
    ['attribute-rich', list(i => h('li', {
      key: i, className: 'row selected', id: 'item-' + i, title: 'Item ' + i,
      role: 'option', tabIndex: 0, 'aria-selected': true, 'data-id': i,
      'data-kind': 'item', dir: 'ltr', draggable: true, hidden: false,
    }, 'Item ' + i))],
    ['inline-styles', list(i => h('li', {key: i, className: 'row', style: commonStyle}, 'Item ' + i))],
    ['long-attributes', list(i => h('li', {
      key: i, className: 'utility-'.repeat(200), title: 'Item ' + i,
      'data-note': 'A normal note. '.repeat(30),
    }, 'Item ' + i))],
  ];
}

function documentWorkloads() {
  function Document({withAttributes}) {
    return h('article', {className: 'document'},
      h('h1', null, 'Rendering guide'),
      Array.from({length: 300}, (_, index) => h('section',
        withAttributes ? {key: index, className: 'section', id: 'section-' + index} : {key: index},
        h('h2', null, 'Section ' + index),
        h('p', null, 'This paragraph explains a supported rendering behaviour. ',
          h('strong', null, 'Important details'), ' are followed by ',
          h('em', null, 'an example'), ' and ordinary text, including café.'),
        h('ul', null, Array.from({length: 3}, (_, point) =>
          h('li', {key: point}, 'Point ' + point + ' in section ' + index))))));
  }
  function Rows() {
    return h('ul', null, Array.from({length: 1000}, (_, index) =>
      h('li', {key: index, className: 'row', title: 'Item ' + index}, 'Item ' + index)));
  }
  return [
    ['fresh-document', h(Document, {withAttributes: false})],
    ['mixed-document', h(Document, {withAttributes: true})],
    ['fresh-row-control', h(Rows)],
    ['text-control', h('pre', null, 'An ordinary line of document text.\n'.repeat(1000))],
  ];
}

async function bench(cases = workloads(), apis = ['node', 'browser', 'legacy'], sampleMs = 100) {
  const rows = [];
  for (const api of apis) {
    for (const [name, element] of cases) {
      const control = await render(api, element);
      for (let i = 0; i < 20; i++) await render(api, element, {collect: false});
      const samples = [];
      for (let sample = 0; sample < 7; sample++) {
        const start = performance.now();
        let count = 0;
        let elapsed;
        do {
          const result = await render(api, element, {collect: false});
          assert.equal(result.bytes, control.bytes);
          count++;
          elapsed = performance.now() - start;
        } while (elapsed < sampleMs && count < 500);
        samples.push({count, elapsedMs: elapsed, msPerRender: elapsed / count});
      }
      rows.push({
        name, api, bytes: control.bytes, sha256: digest(control.html),
        writes: control.writes, maxChunk: control.maxChunk,
        medianMs: samples.map(s => s.msPerRender).sort((a, b) => a - b)[3],
        samples,
      });
    }
  }
  return rows;
}

async function encoderCounts() {
  const originalEncode = TextEncoder.prototype.encode;
  const originalEncodeInto = TextEncoder.prototype.encodeInto;
  let active = false;
  let counts;
  function record(kind, text) {
    if (!active) return;
    counts[kind]++;
    if (/^<[a-z][a-z0-9]*>$/.test(text)) {
      counts.openTags[kind]++;
      counts.openTags.byText[text] = (counts.openTags.byText[text] || 0) + 1;
    }
  }
  TextEncoder.prototype.encode = function (text) {
    record('encode', text);
    return originalEncode.call(this, text);
  };
  TextEncoder.prototype.encodeInto = function (text, destination) {
    record('encodeInto', text);
    return originalEncodeInto.call(this, text, destination);
  };
  const rows = [];
  try {
    for (const api of ['node', 'browser', 'edge']) {
      for (const [name, element] of documentWorkloads().slice(0, 2)) {
        await render(api, element);
        counts = {encode: 0, encodeInto: 0, openTags: {encode: 0, encodeInto: 0, byText: {}}};
        active = true;
        const value = await render(api, element);
        active = false;
        rows.push({api, name, counts, bytes: value.bytes, sha256: digest(value.html)});
      }
    }
  } finally {
    TextEncoder.prototype.encode = originalEncode;
    TextEncoder.prototype.encodeInto = originalEncodeInto;
  }
  return rows;
}

(async () => {
  const started = new Date().toISOString();
  const rows = await (mode === 'matrix' ? matrix()
    : mode === 'focused' ? bench(documentWorkloads(), ['node', 'browser', 'edge'], 150)
    : mode === 'counts' ? encoderCounts()
    : bench());
  const result = {build, mode, node: process.version, react: React.version, started, ended: new Date().toISOString(), rows};
  fs.writeFileSync(output, JSON.stringify(result, null, 2) + '\n');
  console.log(JSON.stringify({mode, cases: rows.length, output}));
  // The browser bundle's module-scoped MessageChannel is not a public handle.
  // All render streams have completed; do not leave its ports alive.
  process.exit(0);
})().catch(error => {
  console.error(error.stack || error);
  process.exit(1);
});
```

