I found a Firefox startup regression in the new cache-invalidation listener. The inline comment has the details.

I checked complete base/head snapshots using the actual reader module and browser API stubs: all three browser cases pass on the base; Firefox alone fails on the head. An optional-event guard makes all 29 diagnostic/fetch tests pass. The nine added suites also pass on the unchanged head in this source harness, so they miss the Firefox API difference.

These checks used Node 20.19.0 and a local Jest source configuration. I haven't run an installed Firefox extension. The Firefox API contract is confirmed by Mozilla's current schema and MDN compatibility data.

<details>
<summary>API fixture and source-test configuration</summary>

Save the fixture beside the existing extension tests and the configuration at the repository root. Run with `NODE_ENV=development RELEASE_CHANNEL=experimental node scripts/jest/jest.js --config ./devtools-jest-source.config.js --silent --no-watchman --runInBand --testPathPatterns=devtools-firefox-compat-test.js`.

```js
/**
 * Copyright (c) Meta Platforms, Inc. and affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 *
 * @flow
 */

describe.each(['Firefox', 'Chrome', 'Edge'])(
  'source reader initialisation in %s',
  browser => {
    let previousFlags;

    beforeEach(() => {
      jest.resetModules();
      jest.useRealTimers();
      previousFlags = [
        global.__IS_FIREFOX__,
        global.__IS_CHROME__,
        global.__IS_EDGE__,
      ];
      global.__IS_FIREFOX__ = browser === 'Firefox';
      global.__IS_CHROME__ = browser === 'Chrome';
      global.__IS_EDGE__ = browser === 'Edge';
    });

    afterEach(() => {
      [
        global.__IS_FIREFOX__,
        global.__IS_CHROME__,
        global.__IS_EDGE__,
      ] = previousFlags;
      delete global.chrome;
    });

    it('loads the devtools-page dependency and reads a cached source', async () => {
      const url = 'https://local.test/component.js';
      const content = 'function Component() { return null; }';
      const listeners = new Set();
      const inspectedWindow = {
        tabId: 1,
        eval: jest.fn(),
        reload: jest.fn(),
      };
      // Firefox exposes eval, reload and tabId, but not the Resource APIs.
      if (browser !== 'Firefox') {
        inspectedWindow.getResources = callback => callback([]);
        inspectedWindow.onResourceContentCommitted = {
          addListener: jest.fn(),
        };
      }
      global.chrome = {
        devtools: {
          inspectedWindow,
          network: {
            onNavigated: {addListener: jest.fn()},
            onRequestFinished: {addListener: jest.fn()},
            getHAR: callback =>
              callback({
                entries: [
                  {
                    request: {url},
                    response: {content: {text: content}},
                    getContent: done => done(content),
                  },
                ],
              }),
          },
        },
        runtime: {
          onMessage: {
            addListener: listener => listeners.add(listener),
            removeListener: listener => listeners.delete(listener),
          },
          sendMessage: message => {
            // The base also starts a redundant page read after a HAR match.
            for (const listener of Array.from(listeners)) {
              listener({
                source: 'react-devtools-background',
                payload: {
                  type: 'fetch-file-with-cache-complete',
                  url,
                  requestID: message.payload.requestID,
                  value: content,
                },
              });
            }
            return Promise.resolve();
          },
        },
      };

      const fetchFileWithCaching =
        require('../main/fetchFileWithCaching').default;
      await expect(fetchFileWithCaching(url)).resolves.toBe(content);
    });
  },
);
